def count_inversions(nums):
    if not nums:
        return 0
    vals = sorted(set(nums))
    ranks = {v: i + 1 for i, v in enumerate(vals)}
    size = len(vals)
    bit = [0] * (size + 1)

    def update(i):
        while i <= size:
            bit[i] += 1
            i += i & -i

    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    inv = 0
    for x in reversed(nums):
        r = ranks[x]
        inv += query(r - 1)
        update(r)
    return inv

