    n = len(nums)
    if n < 2:
        return 0
    max_val = 0
    for x in nums:
        if x > max_val:
            max_val = x
    bitlen = max_val.bit_length()
    candidate = 0
    for b in range(bitlen - 1, -1, -1):
        test = candidate | (1 << b)
        cnt = 0
        for x in nums:
            if x & test == test:
                cnt += 1
                if cnt == 2:
                    candidate = test
                    break
    return candidate
